operations.exampleQuery:
mutation createOrder {
  createOrder(input: {
    externalOrderId: "PED-1001",
    customerCode: "CLI-900",
    items: [{ sku: "7891106001946", quantity: 10 }]
  }) {
    status
    orderId
    message
  }
}

query orderStatus {
  orderStatus(orderId: "GW-123456") {
    status
    updatedAt
    message
  }
}
